<?php
declare(strict_types=1);require __DIR__.'/config.php';require __DIR__.'/functions.php';require_login();$user=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(($_POST['action']??'')==='delete'){$id=(int)($_POST['id']??0);$stmt=$pdo->prepare('SELECT template_image FROM twibbons WHERE id=? AND owner_id=?');$stmt->execute([$id,$user['id']]);if($item=$stmt->fetch()){$pdo->prepare('DELETE FROM twibbons WHERE id=? AND owner_id=?')->execute([$id,$user['id']]);$path=__DIR__.'/uploads/'.basename($item['template_image']);if(is_file($path))@unlink($path);flash('success','Karya berhasil dihapus.');}}redirect('dashboard');}
$flash=pull_flash();$stmt=$pdo->prepare('SELECT t.*,c.name category_name FROM twibbons t LEFT JOIN categories c ON c.id=t.category_id WHERE t.owner_id=? ORDER BY t.created_at DESC');$stmt->execute([$user['id']]);$items=$stmt->fetchAll();$views=array_sum(array_column($items,'view_count'));$uses=array_sum(array_column($items,'use_count'));$downloads=array_sum(array_column($items,'download_count'));
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Studio Kreator — Semarakin</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="teal.css"><link rel="stylesheet" href="auth.css"></head><body><header class="site-header"><div class="container nav"><a class="brand" href="./"><span class="brand-mark">S</span>Semarakin</a></div></header><main class="container"><div class="page-head dashboard-head"><div><span class="eyebrow">Studio kreator</span><h1 class="page-title" style="margin-top:12px">Halo, <?=e(explode(' ',$user['name'])[0])?>.</h1><p class="subtitle">Pantau performa dan kelola seluruh karyamu di satu tempat.</p></div><a class="btn btn-primary" href="karya-baru">＋ Buat karya</a></div><?php if($flash):?><div class="alert alert-<?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif?><div class="dashboard-grid"><div class="card stat"><strong><?=compact_number($views)?></strong><span>Total dilihat</span></div><div class="card stat"><strong><?=compact_number($uses)?></strong><span>Digunakan</span></div><div class="card stat"><strong><?=compact_number($downloads)?></strong><span>Diunduh</span></div></div><section class="dashboard-works"><div class="section-head"><div><h2>Karya saya</h2><p><?=count($items)?> karya tersimpan</p></div><a class="btn btn-secondary btn-sm" href="karya-baru">Tambah karya</a></div><div class="studio-list"><?php foreach($items as $item):?><article class="studio-item"><img src="uploads/<?=e(basename($item['template_image']))?>" alt=""><div><span class="visibility visibility-<?=$item['visibility']==='private'?'private':'unlisted'?>"><?=e($item['visibility'])?></span><h3><?=e($item['title'])?></h3><p><?=e($item['category_name']?:'Tanpa kategori')?> · <?=compact_number((int)$item['view_count'])?> dilihat · <?=compact_number((int)$item['use_count'])?> digunakan</p><div class="template-actions"><a class="btn btn-secondary btn-sm" href="t/<?=e($item['slug'])?>">Buka</a><button class="btn btn-secondary btn-sm" onclick="navigator.clipboard.writeText(new URL('t/<?=e($item['slug'])?>',location.href).href)">Salin link</button></div></div><form method="post" data-confirm="Hapus karya ini secara permanen?"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button class="btn btn-danger btn-sm">Hapus</button></form></article><?php endforeach?></div><?php if(!$items):?><div class="empty"><h3>Belum ada karya</h3><p>Mulai unggah bingkai pertamamu untuk dibagikan.</p><a class="btn btn-primary" href="karya-baru">Buat karya pertama</a></div><?php endif?></section></main><footer class="footer">Semarakin · Produk digital dari Apins Digital</footer></body></html>
